      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11/11) 20~50대 남성) 인공지능(AI) 평가 참여자\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.03. 13:25\n조회 156\n구독\n11/11) 20~50대 남녀) 인공지능(AI) 평가 참여자\n인공지능(AI)이 작성한 글을 읽고 내용과 형식이 사람이 작성한 것과 유사한지를 평가하는 것으로 일반인도 가능한\n간단한 평가입니다!\n참여대상은 20~50대 남녀입니다.\n평가에 대한 구체적인 내용 및 일정/장소 등은 다음과 같습니다.\n[평가내용]\n- AI가 작성한 글을 읽고 내용과 형식이 얼마나 사람이 작성한 것과 유사한지 평가\n- 1인당 약 20개 내외 문장\n- 주관적 의견을 묻는 것이므로 편안하게 작성하면 됨\n[평가일자] 11/11(수) 오전 9시 40분까지 참석(20분 정도 교육 진행 후 평가 진행)\n[소요시간] 9시 40분 ~ 12시\n[평가장소] 서울시 강서구 마곡동 부근 (선정시 세부 주소 안내드립니다)\n[참여대상] 20~50대 남녀\n[사례비] 4만원(평가 종료 후 2~3일내 입금 예정)\n[준비물] 신분증, 볼펜 지참 (신분증 불참시 입장 불가)\n[신청방법]\n이름,성별,나이,연락처\nhttps://forms.gle/riUQFAgVBckAnReU9\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.03. 22:44 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n11/11) 20~50대 여성) 인공지능(AI) 평가 참여자\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11/11) 20~50대 남성) 인공지능(AI) 평가 참여자\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11/21~22) 남자 중 고등학생]_PC로 게임 하시는 중고생_모바일은 거의 안하는 학생\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11/21~22) 여자 중 고등학생]_PC로 게임 하시는 중고생_모바일은 거의 안하는 학생\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
