      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 11/12) 만 20~49세 미혼여성) 뷰티 디바이스 관련 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.03. 14:19\n조회 111\n구독\n고유링크) 11/12) 만 20~49세 여성) 뷰티 디바이스 관련 인터뷰\n- 조사 대상 :\n1. 피부 탄력, 리프팅, 얼굴 윤곽/페이스 라인, 주름 관리에 관심이 있는 만 20~49세 여성\n2. 스킨 케어 제품 구입에 월 평균 5만원 이상 지출하는 자\n3. 자신만의 얼굴 스킨케어 루틴이 있는 자 (피부세안, 세안 후 스킨케어 등)\n4. 향후 6개월 내에 20만원 이상의 홈스킨케어 뷰티 디바이스를 구입할 의향이 있는 자\n* 홈스킨케어 뷰티 디바이스 = LED마스크/넥케어, 갈바닉 이온 마사지기, 초음파/고주파 피부 관리기, 진동/초음파 클렌저 등\n- 조사 일정 : 11월 12일 (목)/ 시간은 추후 안내드립니다\n※ 조사 안내 사항 (필독)\n- 조사 참여 시, 현재 주로 사용하시는 뷰티 디바이스를 지참해주셔야 합니다.\n- 인터뷰 당일에는 메이크업 없이 스킨, 로션 등 기초 제품만 바르고 참석해 주셔야 합니다.\n- 인터뷰 중 테스트용 스킨케어 제품을 직접 발라보시게 되며, 제품 사용 전후 피부상태를 확인하기 위해 얼굴 사진을 촬영할 예정입니다.\n위 조사 안내 사항을 충분히 확인하신 후, 모든 조건에 동의하고 참여 가능하신 분만 신청해 주시기 바랍니다.\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n소요시간 60분\n사례비 5만원\n조사방법 1:1 인터뷰 (60분)\n안내사항\n1. (뷰티 디바이스 제품 보유자일 경우) 뷰티 디바이스 제품을 지참 하셔야 합니다.\n2. 인터뷰 당일에는 메이크업 없이 스킨,로션 등 기초 제품만 바르고 참석해 주셔야 합니다.\n3. 인터뷰 중 테스트용 스킨케어 제품을 직접 발라보시게 되며, 제품사용 전후 피부상태를 확인하기 위해 얼굴 사진을 촬영할 예정입니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/826?refuser=23341&intro=2\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구의 더 많은 인기글 보러가기\n댓글\n2\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n삭제된 댓글입니다.\n좌담회알바좌담회카페\n카페매니저\n작성자\nNew\n감사합니다 리서치회사에 확인 부탁드렸습니다\n2026.11.03. 15:24 답글쓰기\n옵션\n좋아요\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.03. 22:40 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n고유링크) 11/12) 만 20~49세 기혼여성) 뷰티 디바이스 관련 인터뷰\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n고유링크) 11/12) 만 20~49세 미혼여성) 뷰티 디바이스 관련 인터뷰\n좌담회알바좌담회카페\n26.11.03.\n댓글\n2\n고유링크) 11월 중 협의) 30~45분 3만) 50대 이상 남녀) 대기업 재직 직장인 대상 AI 온라인 조사\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n고유링크) 11월 중 협의) 30~45분 3만) 40대 남녀) 대기업 재직 직장인 대상 AI 온라인 조사\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n2\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
