      "title": "지방거주자 AI이슈 공론화 시민토론단 참여의향 조사(2차, 3차)",
      "source": "naver_cafe",
      "source_url": "https://m.cafe.naver.com/togetheralba/130735",
      "target_age": "",
      "target_gender": "",
      "target_condition": "전국 만 19세 이상 대상자",
