      "time": "",
      "duration": "온라인 _ 2시간 / 현장참석_7시간",
      "reward": "150,000원(추후 계좌로 입금 예정)",
      "location": "서울여성플라자(동작구)_추후변경도 개별 연락",
      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n지방거주자 AI이슈 공론화 시민토론단 참여의향 조사(2차, 3차)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.03. 15:51\n조회 87\n구독\n지방거주자 AI이슈 공론화 시민토론단 참여의향 조사(2차, 3차)\n신청하신분은 재신청 안하셔도 됩니다\n지방 참석자의 경우 교통비 실비 지원이 가능하며, 지원 항목은 기차·버스·비행기(제주도 한정)입니다.\n** 영수증 필히 첨부!!!!\n단, 자차 이용 시 교통비는 지원되지 않으며, 서울권 내 이동에 따른 교통비도 지원되지 않는 점 참고 부탁드립니다.\n현재 링크에 있는 날짜는 2차모집 링크입니다.\n2차 3차 중복지원 가능합니다.\n- 주제: 「AI로 만든 허위.조작 정보로부터 우리 사회를 지키면서 표현의 자유도 보장하려면 무엇이 필요할까요?」\n- 온라인 교육: 11월 3일 or 4일 온라인 2시\n- 온라인 의견 작성: 교육 이후 작성(1,000자 이내 작성)\n- 현장 토론회: 11월 12일(목) 10:00~17:00(점심식사제공)\n- 현장 토론회 의견 작성 : 참석일정 이후\n대상 : 전국 만 19세 이상 대상자\n사례비 : 150,000원(추후 계좌로 입금 예정)\n(마지막 CQ4. 의견 자유롭게 작성 부분에 소개 성명 꼭 기입!!)\n장소 : 서울여성플라자(동작구)_추후변경도 개별 연락\n소요시간 : 온라인 _ 2시간 / 현장참석_7시간\n** 중도 참석시 사례비 미지급되는 점 참고!!\n** 본소개는 연락처 전달을 받지않고 하기 링크로만 접수 가능!!!\n참여링크 :\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://survey.metrix.co.kr/?ACCESS_KEY=6ff108106e8540c1ac87&grpid=&UID=\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.03. 22:37 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n11월 중순) 만 15~39세 수도권 거주 남성) 캔디류 맛 테스트\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n지방거주자 AI이슈 공론화 시민토론단 참여의향 조사(2차, 3차)\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11월/14 )고등학생)지구 환경, 미래세대 성장관련, UN의 활동 등 다양한 분야의 인식 관련 좌담회\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11/10~20) 20~64세 남녀) 자동차 BMW 화상 인터뷰\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
