      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11/12~13) 만19세~만39세 남성) 식품 관련 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.03. 16:01\n조회 110\n구독\n11/12~13) 만19세~만39세 남녀) 식품 관련 좌담회\n[모집대상]\n1. 가정 내 식료품 주 구매자\n2. 만 19세 ~ 만 39세 남녀\n2. 일정: 11월 12일, 11월 13일 오전 10시 / 2시 / 4시 진행\n3. 사례비: 50,000원 (계좌이체 지급예정)\n4. 소요시간: 2시간~2시간 30분\n5. 장소: (3호선 경복궁역 인근) *주차불가*\n** 본 좌담회에서는 직접 시식하는 과정이 포함되어 있으며, 일부 제품은 맵기 수준이 매우 높을 수 있습니다.\n** 식품 알레르기(알러지)나 특이체질이 있으시거나, 위장 질환 등으로 매운 음식 섭취가 어려우신 경우, 또는 시식 자체가 불편하신 경우에는 본 조사에 참여하실 수 없습니다.\n[응답자 정보]\n성명/성별/생년월일/만 나이/휴대폰/주소(상세 동까지 기입요망 / 직업+ 직장명 / 식료품 주 구매자 / 최근 1개월 이내 매운음식 섭취여부/ 외식 평균 횟수 (배달, 조리 포함) / 매운 음식 섭취빈도 / 선호요일 및 시간\nhttps://forms.gle/N4g5GaSHEXCNKWp79\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.03. 22:36 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n11/12~13) 만19세~만39세 여성) 식품 관련 좌담회\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11/12~13) 만19세~만39세 남성) 식품 관련 좌담회\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11월 중순) 만 15~39세 수도권 거주 여성) 캔디류 맛 테스트\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11월 중순) 만 15~39세 수도권 거주 남성) 캔디류 맛 테스트\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
