      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\nAX 담당자 DI 인터뷰 비대면 줌 조사-남성\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.03. 16:24\n조회 46\n구독\nAX 담당자 DI 인터뷰 비대면 줌 조사\n본 조사는 「인공지능 기술 발전에 따른 산업 일자리 전환 연구」의 일환으로, 기업의 인공지능 전환(AX) 과정과 관련 직무의 역할 및 업무 변화 등에 대한\n실무자들의 경험과 의견을 파악하기 위한 조사입니다.\n1. 조사 개요\n조사 방식: 비대면(ZOOM) 1:1 심층인터뷰\n소요 시간: 약 60분\n모집 인원: 총 5~6명\n참여 사례비: 1인당 10만 원\n진행 일정: 대상자 섭외 후 연구진과 개별 일정 협의\n2. 모집 대상\nA. AX 관련 업무 담당자\n대상 기업: 삼성SDS, LG CNS, SK AX\n모집 조건: 해당 기업에 현재 재직 중이며, FDE 또는 AX 관련 부서에서 업무를 수행하는 분\n관련 직무 예시: AX 전략·컨설팅, AI 플랫폼 및 솔루션 개발·구축, AI 전환 프로젝트 기획·설계, FDE 등\nB. FDE 담당자\n대상 기업: 채널톡, 세일즈포스\n모집 조건: 해당 기업에 현재 재직 중이며, FDE 직무를 수행하는 분\n※ A·B그룹을 합산하여 총 5~6명 모집 예정입니다.\n3. 대상자 확인 사항\n섭외 시 아래 내용을 확인 부탁드립니다.\n① 성함 및 연락처\n② 현재 재직 기업 및 소속 부서\n③ 현재 직위 및 담당 직무\n④ AX 또는 FDE 관련 주요 업무 내용\n⑤ 관련 업무 수행 경력\nhttps://forms.gle/U1LryQPC4nm5MA6G8\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.03. 22:34 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\nAX 담당자 DI 인터뷰 비대면 줌 조사-여성\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\nAX 담당자 DI 인터뷰 비대면 줌 조사-남성\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11/23~24) 만20-45세 여성) 연담 맛테스트 조사\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n11/23~24) 만20-45세 남성) 연담 맛테스트 조사\n좌담회알바좌담회카페\n26.11.03.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
